// fresh real fd we are allowed to close (a dup of stderr is always valid)
static int fresh_fd(){ return ::dup(2); }
// is fd still open? fcntl(F_GETFD) succeeds iff open.
static bool is_open(int fd){ return ::fcntl(fd, F_GETFD) != -1; }

int main(){
    // 1) default-constructed is empty
    { UniqueFd a; check("default-empty", !a.valid() && a.get()==-1, "empty"); }

    // 2) holds the fd it is given
    { int fd = fresh_fd(); UniqueFd a(fd); check("holds-fd", a.valid() && a.get()==fd, "get==fd"); }

    // 3) destructor closes the owned fd
    int leaked;
    { int fd = fresh_fd(); leaked = fd; UniqueFd a(fd); }
    check("dtor-closes", !is_open(leaked), "closed after scope");

    // 4) move ctor steals + nulls the source
    { int fd = fresh_fd();
      UniqueFd a(fd);
      UniqueFd b(std::move(a));
      check("move-ctor", b.get()==fd && !a.valid() && a.get()==-1, "stolen+nulled"); }

    // 5) move assignment closes the current fd, then steals
    { int f1 = fresh_fd(); int f2 = fresh_fd();
      UniqueFd a(f1);
      UniqueFd b(f2);
      b = std::move(a);                 // must close f2, take f1
      bool ok = b.get()==f1 && !a.valid() && !is_open(f2) && is_open(f1);
      check("move-assign", ok, "old closed, new stolen"); }

    // 6) self-move-assignment is safe (no double close, fd preserved)
    { int fd = fresh_fd();
      UniqueFd a(fd);
      UniqueFd& r = a;
      a = std::move(r);                 // self-assign guard
      check("self-move-safe", a.get()==fd && is_open(fd), "fd preserved"); }

    printf("__SUMMARY__|%d\n", g_fail);
    return g_fail==0?0:1;
}

