#include <cstdio>
#include <thread>
#include <vector>

static int g_fail = 0;
static void check(const char* n, bool ok, const char* d){
    if(!ok) ++g_fail;
    printf("__CASE__|%s|%s|%s\n", n, ok?"PASS":"FAIL", d);
}

int main(){
    TTASLock m;

    // 1) try_lock succeeds on a free lock
    check("trylock-free", m.try_lock()==true, "acquired");

    // 2) try_lock fails while held
    check("trylock-held", m.try_lock()==false, "blocked");

    // 3) unlock then try_lock succeeds again
    m.unlock();
    check("trylock-after-unlock", m.try_lock()==true, "reacquired");
    m.unlock();

    // 4) lock/unlock round trip leaves it acquirable
    m.lock();
    m.unlock();
    check("lock-unlock-roundtrip", m.try_lock()==true, "free again");
    m.unlock();

    // 5) mutual exclusion: 4 threads each add K under the lock; sum must be exact.
    {
        constexpr int THREADS = 4;
        constexpr long K = 50000;           // hard, bounded iteration count
        long counter = 0;
        std::vector<std::thread> ts;
        for (int t = 0; t < THREADS; ++t) {
            ts.emplace_back([&]{
                for (long i = 0; i < K; ++i) {
                    m.lock();
                    ++counter;               // non-atomic: only safe under the lock
                    m.unlock();
                }
            });
        }
        for (auto& th : ts) th.join();
        check("mutual-exclusion", counter == THREADS * K,
              counter == THREADS*K ? "exact total" : "lost updates");
    }

    // 6) lock published critical-section writes (acquire/release): handoff value visible
    {
        TTASLock g;
        long shared = 0;
        bool ready = false;
        g.lock();
        std::thread w([&]{
            g.lock();                        // waits for main to release
            // main's write to `shared` must be visible here
            check("acq-rel-publish", shared == 1234 && ready, "publish visible");
            g.unlock();
        });
        shared = 1234;
        ready = true;
        g.unlock();                          // release publishes shared/ready
        w.join();
    }

    printf("__SUMMARY__|%d\n", g_fail);
    return g_fail==0?0:1;
}

