template <class T, class F>
void atomic_update(std::atomic<T>& a, F f) {
    T old = a.load(std::memory_order_relaxed);
    T desired;
    do {
        desired = f(old);
    } while (!a.compare_exchange_weak(
                 old, desired,
                 std::memory_order_release,
                 std::memory_order_relaxed));
}
