inline bool decode_varint(const uint8_t*& p, const uint8_t* end, uint64_t& out) {
    if (p != end && (*p & 0x80) == 0) {
        out = *p++;
        return true;
    }
    uint64_t result = 0;
    int shift = 0;
    for (int i = 0; i < 10; ++i) {
        if (p == end) return false;
        uint8_t byte = *p++;
        result |= static_cast<uint64_t>(byte & 0x7F) << shift;
        if ((byte & 0x80) == 0) { out = result; return true; }
        shift += 7;
    }
    return false;
}
