// helper: decode a fixed buffer, report success + value + bytes consumed
static bool dec(const std::vector<uint8_t>& v, uint64_t& out, size_t& consumed){
    const uint8_t* p = v.data();
    const uint8_t* end = v.data() + v.size();
    bool ok = decode_varint(p, end, out);
    consumed = static_cast<size_t>(p - v.data());
    return ok;
}

int main(){
    uint64_t out; size_t n;

    // 1) single-byte fast path: 0
    check("zero", dec({0x00}, out, n) && out==0 && n==1, "0 in 1 byte");

    // 2) single-byte: 127 (continuation bit clear)
    check("127", dec({0x7F}, out, n) && out==127 && n==1, "127 in 1 byte");

    // 3) two-byte: 300 -> 0xAC 0x02
    check("300", dec({0xAC,0x02}, out, n) && out==300 && n==2, "300 in 2 bytes");

    // 4) max uint64: ten bytes, all 0xFF... last 0x01
    check("u64-max",
          dec({0xFF,0xFF,0xFF,0xFF,0xFF,0xFF,0xFF,0xFF,0xFF,0x01}, out, n)
            && out==UINT64_MAX && n==10, "UINT64_MAX in 10 bytes");

    // 5) truncated input (continuation bit set, no more bytes) -> false
    check("truncated", dec({0x80}, out, n)==false, "rejects truncated");

    // 6) over-long: 11 continuation bytes -> false (DoS guard)
    check("over-long",
