#include <cstdint>
#include <cstring>

namespace {
inline constexpr char kTwoDigits[201] =
    "00010203040506070809101112131415161718192021222324"
    "25262728293031323334353637383940414243444546474849"
    "50515253545556575859606162636465666768697071727374"
    "75767778798081828384858687888990919293949596979899";

inline unsigned digits10(uint64_t v) {
    unsigned n = 1;
    for (;;) {
        if (v < 10)    return n;
        if (v < 100)   return n + 1;
        if (v < 1000)  return n + 2;
        if (v < 10000) return n + 3;
        v /= 10000u;
        n += 4;
    }
}
} // namespace

inline char* u64toa(uint64_t value, char* buf) {
    unsigned len = digits10(value);
    char* p = buf + len;
    while (value >= 100) {
        unsigned idx = static_cast<unsigned>(value % 100) * 2;
        value /= 100;
        p -= 2;
        std::memcpy(p, &kTwoDigits[idx], 2);
    }
    if (value < 10) {
        *--p = static_cast<char>('0' + value);
    } else {
        unsigned idx = static_cast<unsigned>(value) * 2;
        p -= 2;
        std::memcpy(p, &kTwoDigits[idx], 2);
    }
    return buf + len;
}
