class RingQueue {
    std::size_t cap_, mask_, head_ = 0, size_ = 0;
    std::unique_ptr<std::byte[]> buf_;

    T* slot(std::size_t i) noexcept {
        return std::launder(reinterpret_cast<T*>(buf_.get() + i * sizeof(T)));
    }
    static std::size_t round_pow2(std::size_t n) {
        std::size_t c = 1; while (c < n) c <<= 1; return c;
    }
