    explicit RingQueue(std::size_t want)
        : cap_(round_pow2(want)), mask_(cap_ - 1),
          buf_(new std::byte[cap_ * sizeof(T)]) {}

    ~RingQueue() {
        std::size_t idx = head_;
        for (std::size_t k = 0; k < size_; ++k) {
            slot(idx)->~T();
            idx = (idx + 1) & mask_;
        }
