template <class T>
class PooledQueue {
    struct Node {
        alignas(T) std::byte storage[sizeof(T)];
        Node* next;
        T* value() { return reinterpret_cast<T*>(storage); }
    };
    std::vector<Node> pool_;
    Node* free_head_ = nullptr;
    Node* head_ = nullptr;
    Node* tail_ = nullptr;

    Node* acquire() {
        Node* n = free_head_;
        if (n) free_head_ = n->next;
        return n;
    }
    void release(Node* n) { n->next = free_head_; free_head_ = n; }
public:
    explicit PooledQueue(std::size_t capacity) : pool_(capacity) {
        for (std::size_t i = 0; i < capacity; ++i) {
            pool_[i].next = free_head_;
            free_head_ = &pool_[i];
        }
    }
    ~PooledQueue() {
        for (Node* n = head_; n; n = n->next) n->value()->~T();
    }

    template <class... Args>
    bool try_emplace(Args&&... args) {
        Node* n = acquire();
        if (!n) return false;
        ::new (n->value()) T(std::forward<Args>(args)...);
        n->next = nullptr;
        if (tail_) tail_->next = n; else head_ = n;
        tail_ = n;
        return true;
    }

    std::optional<T> try_pop() {
        if (!head_) return std::nullopt;
        Node* n = head_;
        std::optional<T> out(std::move(*n->value()));
        n->value()->~T();
        head_ = n->next;
        if (!head_) tail_ = nullptr;
        release(n);
        return out;
    }
};
