#include <new>
#include <array>

#ifdef __cpp_lib_hardware_interference_size
  inline constexpr std::size_t CL = std::hardware_destructive_interference_size;
#else
  inline constexpr std::size_t CL = 64;
#endif

template <class T, std::size_t N>
class SpscQueue {
    static_assert((N & (N - 1)) == 0, "N must be a power of two");
    static constexpr std::size_t MASK = N - 1;

    std::array<T, N> slots_{};
    alignas(CL) std::atomic<std::size_t> writeIdx_{0};
    alignas(CL) std::atomic<std::size_t> readIdx_{0};
public:
    bool push(const T& v) {
        const std::size_t w = writeIdx_.load(std::memory_order_relaxed);
        const std::size_t next = (w + 1) & MASK;
        if (next == readIdx_.load(std::memory_order_acquire))
            return false;
        slots_[w] = v;
        writeIdx_.store(next, std::memory_order_release);
        return true;
    }
    bool pop(T& out) {
        const std::size_t r = readIdx_.load(std::memory_order_relaxed);
        if (r == writeIdx_.load(std::memory_order_acquire))
            return false;
        out = slots_[r];
        readIdx_.store((r + 1) & MASK, std::memory_order_release);
        return true;
    }
};
