#include <atomic>

struct MpscNode {
    std::atomic<MpscNode*> next{nullptr};
    // ... caller payload ...
};

class MpscQueue {
    MpscNode  stub_;
    std::atomic<MpscNode*> tail_{&stub_};
    MpscNode* head_{&stub_};
public:
    void push(MpscNode* n) {
        n->next.store(nullptr, std::memory_order_relaxed);
        MpscNode* prev = tail_.exchange(n, std::memory_order_acq_rel);
        prev->next.store(n, std::memory_order_release);
    }

    MpscNode* pop() {
        MpscNode* head = head_;
        MpscNode* next = head->next.load(std::memory_order_acquire);
        if (head == &stub_) {
            if (next == nullptr) return nullptr;
            head_ = next;
            head  = next;
            next  = head->next.load(std::memory_order_acquire);
        }
        if (next != nullptr) {
            head_ = next;
            return head;
        }
        if (head != tail_.load(std::memory_order_acquire))
            return nullptr;
        push(&stub_);
        next = head->next.load(std::memory_order_acquire);
        if (next != nullptr) { head_ = next; return head; }
        return nullptr;
    }
};
