    { MpscQueue q; check("empty-pop", q.pop()==nullptr, "nullptr"); }

    // 2) single push then pop returns that node
    { MpscQueue q; PNode a(7);
      q.push(&a);
      MpscNode* got = q.pop();
      check("single", got==&a && static_cast<PNode*>(got)->val==7, "==7"); }

    // 3) single-threaded FIFO order
    { MpscQueue q;
      PNode n0(0), n1(1), n2(2), n3(3);
      q.push(&n0); q.push(&n1); q.push(&n2); q.push(&n3);
      bool ok=true;
      for (uint64_t i=0;i<4;++i){
          MpscNode* g = q.pop();
          // retry-tolerant: in single-thread it is immediately available
          if(!g || static_cast<PNode*>(g)->val != i){ ok=false; break; }
      }
      check("fifo", ok && q.pop()==nullptr, "0,1,2,3"); }

    // 4) drains exactly the pushed count
    { MpscQueue q;
      constexpr int M=64;
      std::deque<PNode> nodes;              // deque never relocates existing elements
