      for (int i=0;i<M;++i) q.push(&nodes[i]);
      int popped=0; while (q.pop()) ++popped;
      check("count", popped==M, popped==M?"64 popped":"miscount"); }

    // 5) multi-producer / single-consumer: sum of received payloads is exact.
    //    pop() may transiently return nullptr (a push is mid-flight) -> retry.
    {
        constexpr int PRODUCERS = 4;
        constexpr uint64_t PER = 25000;            // hard bound
        constexpr uint64_t TOTAL = PRODUCERS * PER;
        // each producer pushes PER nodes of value 1; consumer sums to TOTAL.
        std::deque<std::deque<PNode>> store(PRODUCERS);   // deque: stable addresses, no move needed
        for (auto& v : store){ for (uint64_t i=0;i<PER;++i) v.emplace_back(1); }

        MpscQueue q;
        std::atomic<bool> done_producing{false};
        uint64_t sum = 0, received = 0;

        std::thread cons([&]{
            while (received < TOTAL) {
                MpscNode* n = q.pop();
                if (n) { sum += static_cast<PNode*>(n)->val; ++received; }
                else if (done_producing.load(std::memory_order_acquire) && received >= TOTAL) break;
            }
