#include <list>
#include <unordered_map>
#include <cstddef>
#include <utility>

template <class K, class V>
class LfuCache {
    struct Info { V value; std::size_t freq; typename std::list<K>::iterator pos; };
    std::size_t cap_;
    std::size_t min_freq_ = 0;
    std::unordered_map<K, Info> keys_;
    std::unordered_map<std::size_t, std::list<K>> freq_;

    void touch(const K& key, Info& info) {
        std::size_t f = info.freq;
        freq_[f].erase(info.pos);
        if (freq_[f].empty()) {
            freq_.erase(f);
            if (min_freq_ == f) ++min_freq_;
        }
        info.freq = f + 1;
        freq_[f + 1].push_front(key);
        info.pos = freq_[f + 1].begin();
    }
public:
    explicit LfuCache(std::size_t cap) : cap_(cap) { keys_.reserve(cap * 2); }

    bool get(const K& key, V& out) {
        auto it = keys_.find(key);
        if (it == keys_.end()) return false;
        touch(key, it->second);
        out = it->second.value;
        return true;
    }

    void put(const K& key, V value) {
        if (cap_ == 0) return;
        auto it = keys_.find(key);
        if (it != keys_.end()) {
            it->second.value = std::move(value);
            touch(key, it->second);
            return;
        }
        if (keys_.size() == cap_) {
            auto& lane = freq_[min_freq_];
            const K victim = lane.back();
            lane.pop_back();
            if (lane.empty()) freq_.erase(min_freq_);
            keys_.erase(victim);
        }
        freq_[1].push_front(key);
        keys_[key] = Info{ std::move(value), 1, freq_[1].begin() };
        min_freq_ = 1;
    }
};
