#include <vector>
#include <unordered_map>
#include <cstdint>

using OrderId = std::uint64_t;
using Price   = std::int32_t;   // dense integer ticks
using Qty     = std::int64_t;
enum class Side { Buy, Sell };

struct Order {
    OrderId id; Qty qty; Price price; Side side;
    Order *prev = nullptr, *next = nullptr;   // intrusive FIFO within a level
};

struct Level {
    Order* head = nullptr;     // oldest (fills first)
    Order* tail = nullptr;     // newest (append here)
    Qty total_qty = 0;
    void push_back(Order* o) {
        o->prev = tail; o->next = nullptr;
        (tail ? tail->next : head) = o;
        tail = o; total_qty += o->qty;
    }
    void unlink(Order* o) {
        (o->prev ? o->prev->next : head) = o->next;
        (o->next ? o->next->prev : tail) = o->prev;
        total_qty -= o->qty;
    }
    bool empty() const { return head == nullptr; }
};

class OrderBook {
    Price base_;
    std::vector<Level> levels_;                 // indexed by price - base_
    std::vector<Order> pool_;  Order* free_ = nullptr;
    std::unordered_map<OrderId, Order*> by_id_;
    Price best_bid_ = -1, best_ask_ = -1;        // -1 = none (sentinel)

    Level& lvl(Price p) { return levels_[p - base_]; }
    std::size_t idx(Price p) const { return static_cast<std::size_t>(p - base_); }
    Order* alloc() {
        Order* o = free_;
        if (o) free_ = o->next;
        else { pool_.emplace_back(); o = &pool_.back(); }
        return o;
    }
    void dealloc(Order* o) { o->next = free_; free_ = o; }

    // walk to the next occupied level after `emptied` for the given side
    void reseat_best(Side s, Price emptied) {
        if (s == Side::Buy) {
            if (emptied != best_bid_) return;          // best did not change
            Price p = emptied - 1;                     // bids: scan downward
            while (p >= base_ && lvl(p).empty()) --p;
            best_bid_ = (p >= base_) ? p : -1;
        } else {
            if (emptied != best_ask_) return;
            Price hi = base_ + static_cast<Price>(levels_.size()) - 1;
            Price p = emptied + 1;                     // asks: scan upward
            while (p <= hi && lvl(p).empty()) ++p;
            best_ask_ = (p <= hi) ? p : -1;
        }
    }
public:
    OrderBook(Price lo, Price hi, std::size_t maxOrders)
        : base_(lo), levels_(hi - lo + 1) {
        pool_.reserve(maxOrders);
        by_id_.reserve(maxOrders * 2);
    }

    void add(OrderId id, Side s, Price p, Qty q) {       // O(1)
        Order* o = alloc(); *o = Order{id, q, p, s, nullptr, nullptr};
        lvl(p).push_back(o);
        by_id_[id] = o;
        if (s == Side::Buy) { if (best_bid_ < 0 || p > best_bid_) best_bid_ = p; }
        else                { if (best_ask_ < 0 || p < best_ask_) best_ask_ = p; }
    }

    void cancel(OrderId id) {                            // O(1) (+ amortized reseat)
        auto it = by_id_.find(id);
        if (it == by_id_.end()) return;
        Order* o = it->second;
        Side s = o->side; Price p = o->price;
        Level& L = lvl(p);
        L.unlink(o);
        by_id_.erase(it);
        dealloc(o);
        if (L.empty()) reseat_best(s, p);
    }

    // --- accessors for testing ---
    Price best_bid() const { return best_bid_; }
    Price best_ask() const { return best_ask_; }
    Qty   level_qty(Price p) { return levels_[idx(p)].total_qty; }
    bool  has_order(OrderId id) const { return by_id_.count(id) != 0; }
    // first (oldest) order id resting at a price level, or 0 if none
    OrderId front_id(Price p) { Order* h = levels_[idx(p)].head; return h ? h->id : 0; }
};
