    std::size_t idx(Price p) const { return static_cast<std::size_t>(p - base_); }
    Order* alloc() {
        Order* o = free_;
        if (o) free_ = o->next;
        else { pool_.emplace_back(); o = &pool_.back(); }
        return o;
    }
    void dealloc(Order* o) { o->next = free_; free_ = o; }

    void reseat_best(Side s, Price emptied) {
        // TODO: if `emptied` was the best for side s, walk to the next occupied
        //       level (bids scan down, asks scan up) and update best_bid_/best_ask_,
        //       or set it to -1 if that side is now empty.
        (void)s; (void)emptied;
    }
public:
    OrderBook(Price lo, Price hi, std::size_t maxOrders)
        : base_(lo), levels_(hi - lo + 1) {
        pool_.reserve(maxOrders);
        by_id_.reserve(maxOrders * 2);
    }

    void add(OrderId id, Side s, Price p, Qty q) {       // O(1)
        // TODO: alloc a node, push_back onto lvl(p), record in by_id_,
        //       update best_bid_/best_ask_ incrementally.
        (void)id; (void)s; (void)p; (void)q;
    }

    void cancel(OrderId id) {                            // O(1)
        // TODO: find via by_id_, intrusively unlink from its level, erase from by_id_,
        //       return the node to the pool, reseat_best if the level emptied.
        (void)id;
    }

    // --- accessors for testing ---
    Price best_bid() const { return best_bid_; }
    Price best_ask() const { return best_ask_; }
    Qty   level_qty(Price p) { return levels_[idx(p)].total_qty; }
    bool  has_order(OrderId id) const { return by_id_.count(id) != 0; }
    OrderId front_id(Price p) { Order* h = levels_[idx(p)].head; return h ? h->id : 0; }
};

