using Tick   = std::int64_t;
using Handle = std::uint64_t;

class Scheduler {
    struct Node { Tick when; Handle h; std::function<void()> action; };
    std::vector<Node> heap_;
    std::unordered_map<Handle, std::size_t> pos_;   // handle -> heap index
    Handle next_ = 1;

    void swap_nodes(std::size_t a, std::size_t b) {
        std::swap(heap_[a], heap_[b]);
        pos_[heap_[a].h] = a;
        pos_[heap_[b].h] = b;
    }
    void sift_up(std::size_t i) {
        while (i && heap_[(i - 1) / 2].when > heap_[i].when) { swap_nodes(i, (i - 1) / 2); i = (i - 1) / 2; }
    }
    void sift_down(std::size_t i) {
        std::size_t n = heap_.size();
        for (;;) {
            std::size_t l = 2*i+1, r = 2*i+2, m = i;
            if (l < n && heap_[l].when < heap_[m].when) m = l;
            if (r < n && heap_[r].when < heap_[m].when) m = r;
            if (m == i) break;
            swap_nodes(i, m); i = m;
        }
    }
    void remove_at(std::size_t i) {
        std::size_t last = heap_.size() - 1;
        pos_.erase(heap_[i].h);
        if (i != last) { heap_[i] = std::move(heap_[last]); pos_[heap_[i].h] = i; }
        heap_.pop_back();
        if (i < heap_.size()) { sift_down(i); sift_up(i); }
    }
public:
    Handle schedule(Tick when, std::function<void()> action) {
        Handle h = next_++;
        heap_.push_back(Node{when, h, std::move(action)});
        pos_[h] = heap_.size() - 1;
        sift_up(heap_.size() - 1);
        return h;
    }
    void cancel(Handle h) {
        auto it = pos_.find(h);
        if (it != pos_.end()) remove_at(it->second);
    }
    template <class Sink>
    void poll(Tick now, Sink&& sink) {
        while (!heap_.empty() && heap_.front().when <= now) {
            Node n = std::move(heap_.front());
            remove_at(0);
            sink(std::move(n.action));
        }
    }
    bool empty() const { return heap_.empty(); }
};
