    { Scheduler s;
      std::vector<int> order;
      s.schedule(30, [&]{ order.push_back(30); });
      s.schedule(10, [&]{ order.push_back(10); });
      s.schedule(20, [&]{ order.push_back(20); });
      s.poll(20, [](std::function<void()> a){ a(); });   // fire <=20
      bool ok = order.size()==2 && order[0]==10 && order[1]==20;
      check("due-order", ok, "10 then 20"); }

    // 3) not-yet-due items remain until their time
    { Scheduler s;
      bool fired=false;
      s.schedule(100, [&]{ fired=true; });
      s.poll(50, [](std::function<void()> a){ a(); });
      bool still = !fired && !s.empty();
      s.poll(100, [](std::function<void()> a){ a(); });
      check("future-waits", still && fired && s.empty(), "fires at 100"); }

    // 4) cancel removes an arbitrary (non-top) item so it never fires
    { Scheduler s;
      bool a_fired=false, c_fired=false;
      s.schedule(10, [&]{ a_fired=true; });
      Handle hb = s.schedule(20, []{ });
      s.schedule(30, [&]{ c_fired=true; });
      s.cancel(hb);                                       // cancel the middle one
      int count=0;
      s.poll(100, [&](std::function<void()> act){ act(); ++count; });
      check("cancel-middle", a_fired && c_fired && count==2 && s.empty(), "b skipped"); }

    // 5) cancel the soonest (top) item
    { Scheduler s;
      Handle h1 = s.schedule(5, []{ });
      bool later=false;
      s.schedule(15, [&]{ later=true; });
      s.cancel(h1);
      int count=0;
      s.poll(100, [&](std::function<void()> act){ act(); ++count; });
      check("cancel-top", later && count==1, "top cancelled"); }

    // 6) many items fire in full sorted order
    { Scheduler s;
      std::vector<int> got;
      int seq[] = {7,3,9,1,5,8,2,6,4,0};
      for (int x : seq) s.schedule(x, [&,x]{ got.push_back(x); });
      s.poll(100, [](std::function<void()> a){ a(); });
      bool sorted=true; for (int i=0;i<10;++i) if (got[i]!=i) sorted=false;
      check("heap-order", got.size()==10 && sorted, "0..9 in order"); }

